import {uid,VERSION,clone,normalize,evaluate,targetGroups,regionQuestions,checkRegions,progressFor,memberDone,makeQueue,cleanWord,parseImport,importChanges,exportCollection,entities,safeId} from './core.js';
import {Store} from './store.js';
import {Sync} from './sync.js';

const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4z M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h3z',learn:'m10 4 10 8-10 8z M4 4v16',refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-1l2 6 M4 12l2 6a7 7 0 0 0 12-1',settings:'M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2 2m8.8 8.8 2 2M5.6 18.4l2-2m8.8-8.8 2-2 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4 10-10',edit:'m14 5 5 5M4 20l5-1L20 8l-5-5L4 14z',upload:'M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5',download:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',chart:'M4 20V12m8 8V4m8 16v-8',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',cloud:'M6 18a5 5 0 0 1-1-10 7 7 0 0 1 13 0 5 5 0 0 1 0 10z',folder:'M3 6h7l2 3h9v11H3z',pause:'M8 5v14M16 5v14'};
const icon=name=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const button=(action,label,kind='primary',extra='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const dirLabel=dir=>dir==='de-en'?'Deutsch → Englisch':dir==='en-de'?'Englisch → Deutsch':'Beide Richtungen';
const gradeLabel=g=>({full:'Richtig',partial:'Teilweise',wrong:'Wiederholen',new:'Neu'}[g]||g);
const groupLabel=g=>g.answers.join(' / ');
const wordLabel=(w,lang)=>w[lang].map(groupLabel).join(', ');
const sorted=object=>Object.values(object).sort((a,b)=>a.name.localeCompare(b.name,'de',{numeric:true}));
const store=await new Store().open(),sync=new Sync(store),data=()=>store.data;
let screen='learn',detail=null,search='',candidate=null,importKind=null,flow=null,toastTimer=null,sessionTimer=null,renderTimer=null,busy=false,updateReady=null,lastFocus=null;
const prefs=()=>({direction:'mixed',requirement:'any',limit:10,...data().settings.training});
const current=()=>{const s=store.doc.session;const item=s?.queue[s.cursor];return {s,item,word:item?data().words[item.wordId]:null};};
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function showDialog(title,body){lastFocus=document.activeElement;modal.innerHTML=`<header class="dialog-head"><h2 id="modal-title">${h(title)}</h2><button class="iconbtn" data-action="close" aria-label="Schließen">${icon('close')}</button></header><div class="dialog-body"><div class="form-error" role="alert"></div>${body}</div>`;if(!modal.open)modal.showModal();}
function closeDialog(){modal.close();modal.innerHTML='';lastFocus?.focus?.({preventScroll:true});}
function error(message){const target=modal.open?modal.querySelector('.form-error'):null;if(target){target.textContent=message;target.scrollIntoView({block:'nearest'});}else notify(message);}
function status(){return `<button class="status" data-action="cloud-settings" data-state="${sync.status}" title="${h(sync.message)}"><span class="dot"></span><span>${h(sync.status==='error'?'Cloud prüfen':sync.message)}</span></button>`;}
function renderStatus(){document.querySelectorAll('[data-sync]').forEach(el=>el.innerHTML=status());}
function shell(body){app.innerHTML=`<div class="shell"><header class="masthead"><button class="brand" data-action="nav" data-screen="learn"><img src="./icon.svg" alt="">wordlo<small>ENGLISH, EVERY DAY</small></button><div data-sync>${status()}</div></header><nav class="navigation" aria-label="Hauptnavigation">${[['learn','learn','Lernen'],['collections','folder','Sammlungen'],['refresh','refresh','Auffrischen'],['settings','settings','Einstellungen']].map(([id,i,label])=>`<button data-action="nav" data-screen="${id}" class="${screen===id?'active':''}" ${screen===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav>${updateReady?`<div class="update-banner">Eine neue Wordlo-Version ist bereit.<button class="textbtn" data-action="update">Jetzt aktualisieren</button></div>`:''}<main class="page">${body}</main></div>`;}
function render(){
  if(screen==='round'){renderRound();return;}if(screen==='result'){renderResult();return;}
  if(detail && !data().collections[detail]&&!data().decks[detail])detail=null;
  shell(screen==='learn'?learnView():screen==='settings'?settingsView():detail?detailView():collectionsView(screen==='refresh'));
}
function learnView(){
  const d=data(),p=prefs(),words=Object.values(d.words),today=new Date().toDateString();
  const reviews=Object.values(d.reviews).filter(r=>!r.repeat),done=reviews.filter(r=>new Date(r.at).toDateString()===today).length;
  const known=words.filter(w=>['de-en','en-de'].every(dir=>progressFor(w,d.reviews,dir,p.requirement).level==='known')).length;
  const resume=store.doc.session&&!store.doc.session.finished;
  const recent=sorted(d.collections).slice(0,3);
  return `${resume?`<div class="notice resume"><div class="grow"><strong>Deine Runde wartet.</strong><p>${store.doc.session.cursor} von ${store.doc.session.queue.length} Aufgaben bearbeitet.</p></div><button class="textbtn" data-action="resume">Fortsetzen ${icon('arrow')}</button></div>`:''}<section class="hero"><div><div class="eyebrow">DEIN ENGLISCH. DEIN TEMPO.</div><h1>Ein Wort näher.<br>Jeden Tag.</h1><p>${words.length?'Eine kleine Runde, die zu dir passt. Übe deine Buchvokabeln in beide Richtungen.':'Deine Buchvokabeln bekommen ein Zuhause. Lege deine erste Sammlung an oder importiere sie.'}</p>${button(words.length?'setup':'import',icon(words.length?'learn':'upload')+(words.length?'Lernrunde starten':'Erste Sammlung importieren'))}</div><div class="art" aria-hidden="true"><div class="art-card back"><small>DEUTSCH</small>ein Wort</div><div class="art-card front"><small>ENGLISH</small>a word</div><span class="spark">✳</span></div></section><section class="stats" aria-label="Dein Lernstand">${[[words.length,'Vokabeln gesammelt','book'],[done,'Heute geübt','spark'],[known,'In beide Richtungen sicher','check']].map(([n,t,i])=>`<div class="stat"><div class="badge-icon">${icon(i)}</div><div><strong>${n}</strong><p>${t}</p></div></div>`).join('')}</section><div class="columns"><section class="panel"><div class="panel-head"><h2>Deine Richtungen</h2><span class="pill">${p.requirement==='all'?'Alle Bedeutungen':'Eine reicht'}</span></div>${['de-en','en-de'].map(dir=>{const safe=words.filter(w=>progressFor(w,d.reviews,dir,p.requirement).level==='known').length;return `<div class="direction-line"><div class="line-label"><strong>${dirLabel(dir)}</strong><span class="muted">${safe} / ${words.length} sicher</span></div><div class="track" aria-label="${safe} von ${words.length} sicher"><i style="width:${words.length?safe/words.length*100:0}%"></i></div></div>`;}).join('')}<p class="small muted">Im Mix kommt deine schwächere Richtung häufiger dran.</p></section><section class="panel"><div class="panel-head"><h2>Deine Sammlungen</h2><button class="textbtn" data-action="nav" data-screen="collections">Alle ${icon('arrow')}</button></div>${recent.length?recent.map(c=>`<div class="history-line"><span>${h(c.name)}</span><button class="textbtn" data-action="open" data-id="${c.id}">${Object.values(d.words).filter(w=>w.collectionId===c.id).length} Wörter ${icon('arrow')}</button></div>`).join(''):`<p class="small muted">Hier lernst du ausschließlich mit deinen eigenen Buchinhalten.</p>${button('new-collection',icon('plus')+'Sammlung anlegen','secondary','style="margin-top:20px"')}`}</section></div>`;
}
function collectionsView(refresh){
  const d=data(),items=sorted(refresh?d.decks:d.collections),title=refresh?'Auffrischen':'Deine Sammlungen';
  return `<header class="pagehead"><div><div class="eyebrow muted">${refresh?'WIEDER SICHER WERDEN':'DEIN WORTSCHATZ'}</div><h1 style="margin-top:9px">${title}</h1><p class="muted">${refresh?'Genau die Wörter, die noch etwas Übung brauchen.':'Dein Buch. Deine Lektionen. Deine Wörter.'}</p></div><div class="row wrap">${button('import',icon('upload')+'Importieren','secondary',`data-kind="${refresh?'refresh':'collection'}"`)}${button(refresh?'new-deck':'new-collection',icon('plus')+'Neu')}</div></header>${items.length?`<div class="toolbar"><input class="search" data-search="collections" aria-label="Sammlungen suchen" placeholder="Sammlung suchen …" value="${h(search)}"><button class="textbtn" data-action="toggle-all" data-value="true">Alle an</button><span class="muted">·</span><button class="textbtn" data-action="toggle-all" data-value="false">Alle aus</button></div><div class="collection-grid" id="collection-results">${collectionCards(items,refresh)}</div>`:`<div class="empty"><div class="badge-icon">${icon(refresh?'refresh':'folder')}</div><h2>${refresh?'Was möchtest du auffrischen?':'Platz für deine erste Lektion.'}</h2><p>${refresh?'Wähle Wörter aus, finde sie in einem Test oder importiere deine Auswahl vom Papier als JSON-Datei.':'Füge deine Wörter hinzu oder importiere eine vorbereitete JSON-Datei.'}</p>${button(refresh?'new-deck':'new-collection',icon('plus')+(refresh?'Auffrisch-Sammlung anlegen':'Sammlung anlegen'))}</div>`}`;
}
function collectionCards(items,refresh){const d=data(),p=prefs();return items.filter(c=>normalize(c.name).includes(normalize(search))).map(c=>{
  const words=refresh?(c.members||[]).map(m=>d.words[m.wordId]).filter(Boolean):Object.values(d.words).filter(w=>w.collectionId===c.id);
  const count=refresh?(c.members||[]).filter(m=>d.words[m.wordId]&&!memberDone(d.words[m.wordId],m,d.reviews,p.direction,p.requirement)).length:words.length;
  return `<article class="collection-card ${refresh?'refresh':''}"><div class="row between"><div class="card-icon">${icon(refresh?'refresh':'folder')}</div><label class="toggle-label"><input type="checkbox" class="toggle" data-toggle="${refresh?'decks':'collections'}" data-id="${c.id}" ${c.active!==false?'checked':''} aria-label="${h(c.name)} aktivieren"></label></div><button class="card-main" data-action="open" data-id="${c.id}"><h3>${h(c.name)}</h3><p class="small muted">${words.length} ${words.length===1?'Vokabel':'Vokabeln'}${refresh?` · ${count} offen`:''}</p></button><div class="footer"><span class="pill">${c.active!==false?'Aktiv':'Pausiert'}</span><button class="textbtn" data-action="setup" data-id="${c.id}">Üben ${icon('arrow')}</button></div></article>`;
}).join('')||'<p class="empty-inline">Keine passende Sammlung.</p>';}
function detailView(){
  const d=data(),deck=d.decks[detail],c=deck||d.collections[detail];
  return `<button class="textbtn back" data-action="back">${icon('back')} ${deck?'Auffrischen':'Sammlungen'}</button><header class="pagehead"><div class="grow"><div class="eyebrow muted">${deck?'AUFFRISCH-SAMMLUNG':'SAMMLUNG'}</div><h1 style="margin-top:9px">${h(c.name)}</h1></div><button class="iconbtn" data-action="rename" data-id="${c.id}" aria-label="Sammlung umbenennen">${icon('edit')}</button></header><div class="toolbar">${button('setup',icon('learn')+'Üben','primary',`data-id="${c.id}"`)}${button(deck?'deck-pick':'new-word',icon('plus')+'Wörter hinzufügen','secondary',`data-id="${c.id}"`)}${deck?button('deck-test',icon('check')+'Mit Test auswählen','secondary',`data-id="${c.id}"`):''}<button class="iconbtn" data-action="export" data-id="${c.id}" aria-label="Sammlung exportieren">${icon('download')}</button><button class="iconbtn" data-action="delete-collection" data-id="${c.id}" aria-label="Sammlung löschen">${icon('trash')}</button><input class="search" data-search="words" aria-label="Vokabeln suchen" placeholder="Vokabel suchen …" value="${h(search)}"></div>${deck?'<p class="small muted" style="margin-bottom:16px">„Offen“ richtet sich nach deiner zuletzt gewählten Richtung und Bedeutungsanzahl. Mit „Alle wiederholen“ übst du auch erledigte Wörter.</p>':''}<div class="word-list" id="word-results">${wordRows()}</div>`;
}
function wordRows(){const d=data(),deck=d.decks[detail],p=prefs();let words=deck?(deck.members||[]).map(m=>d.words[m.wordId]).filter(Boolean):Object.values(d.words).filter(w=>w.collectionId===detail);
  words=words.filter(w=>normalize(wordLabel(w,'english')+' '+wordLabel(w,'german')).includes(normalize(search)));
  return words.map(w=>`<article class="word-row"><div class="grow"><strong lang="en">${h(wordLabel(w,'english'))}</strong><p>${h(wordLabel(w,'german'))}</p><div class="word-status">${['de-en','en-de'].map(dir=>{const level=progressFor(w,d.reviews,dir,p.requirement).level;return `<span class="pill ${level}">${dir==='de-en'?'DE → EN':'EN → DE'} · ${{new:'Neu',learning:'In Übung',known:'Sicher'}[level]}</span>`;}).join('')}${deck?`<span class="pill">${memberDone(w,deck.members.find(m=>m.wordId===w.id),d.reviews,p.direction,p.requirement)?'Erledigt':'Offen'}</span>`:''}</div></div><div class="word-actions"><button class="iconbtn" data-action="word-stats" data-id="${w.id}" aria-label="Lernstand für ${h(w.english[0].answers[0])}">${icon('chart')}</button><button class="iconbtn" data-action="edit-word" data-id="${w.id}" aria-label="${h(w.english[0].answers[0])} bearbeiten">${icon('edit')}</button>${deck?`<button class="iconbtn" data-action="remove-member" data-id="${w.id}" aria-label="Aus Auffrisch-Sammlung entfernen">${icon('close')}</button>`:''}</div></article>`).join('')||'<div class="empty-inline">Hier sind noch keine passenden Vokabeln.</div>';
}
function settingsView(){const c=store.doc.config;return `<header class="pagehead"><div><div class="eyebrow muted">ALLES AN SEINEM PLATZ</div><h1 style="margin-top:9px">Einstellungen</h1></div></header><div class="settings-grid"><section class="panel"><h2>Deine Google-Verbindung</h2><p>Ein Lernstand auf deinem iPhone, iPad und Computer. Ohne Verbindung kannst du auf diesem Gerät weiterlernen.</p><div class="cloud-summary"><strong>${h(sync.message)}</strong><span class="muted">${store.doc.lastSync?'Letzter Abgleich: '+new Date(store.doc.lastSync).toLocaleString('de-DE'):'Noch kein Cloud-Abgleich'}${c.url?` · ${store.doc.pending.length} Änderungen offen`:''}</span></div>${sync.conflicts.length?button('conflicts','Änderungen vergleichen','lavender','class="wide"'):''}<form id="cloud-form"><label class="field">Wordlo-Web-App-Adresse<input name="url" type="url" autocomplete="off" value="${h(c.url)}" placeholder="https://script.google.com/macros/s/…/exec" required></label><label class="field">Privater Verbindungsschlüssel<input name="token" type="password" autocomplete="off" placeholder="${c.token?'Gespeichert · leer lassen zum Beibehalten':'Dein Schlüssel aus der Einrichtung'}" ${c.token?'':'required'}></label><div class="row wrap"><button class="btn primary" type="submit">${icon('cloud')} Verbindung speichern</button>${c.url?button('sync','Jetzt abgleichen','secondary'):''}</div></form><details><summary>Google-Verbindung einrichten</summary><p class="small muted">Wordlo benötigt eine eigene Google-Tabelle und das mitgelieferte Wordlo-Skript.</p><div class="link-list space"><a href="./EINRICHTUNG.html" target="_blank" rel="noopener">Einrichtung Schritt für Schritt</a><a href="./google/Code.gs" download>Google-Skript herunterladen</a><a href="./google/Bridge.html" download>Verbindungsdatei herunterladen</a></div></details></section><div class="stack"><section class="panel"><h2>Import & Sicherung</h2><p>Buchvokabeln und Auffrisch-Sammlungen werden beim Import automatisch unterschieden.</p><div class="stack" style="gap:10px">${button('import',icon('upload')+'JSON-Datei importieren','secondary')}${button('backup',icon('download')+'Gesamten Lernstand sichern','secondary')}</div><details><summary>Vorlagen für den Import</summary><div class="link-list"><a href="./examples/sammlung.json" download>Vorlage: normale Sammlung</a><a href="./examples/auffrischen.json" download>Vorlage: Auffrisch-Sammlung</a><a href="./IMPORTFORMAT.md" target="_blank" rel="noopener">Importformat erklärt</a></div><p class="hint space">Die Vorlagen enthalten ausdrücklich nur Beispieldaten, keine Vokabeln aus deinem Buch.</p></details></section><section class="panel"><h2>So wird bewertet</h2><p><strong>Deutsch:</strong> Autokorrektur ist erlaubt. Kleine Tippfehler zählen als richtig; übersehene Tippfehler kannst du korrigieren.</p><p><strong>Englisch:</strong> Autokorrektur und Rechtschreibprüfung werden abgeschaltet. Schreibweise und Groß-/Kleinschreibung zählen.</p><p>Eine oder alle Bedeutungen entscheidest du vor jeder Runde. Es gelten ausschließlich deine hinterlegten Buchantworten.</p></section><section class="panel"><h2>Als App verwenden</h2><p>Auf dem iPhone: Safari → Teilen → Zum Home-Bildschirm. Nach dem ersten Laden ist Wordlo auch offline nutzbar.</p>${button('check-update','Nach App-Update suchen','secondary')}</section></div></div><p class="version">Wordlo ${VERSION} · Dein persönlicher Wortschatz</p>`;}

function options(name,values,selected,two=false){return `<div class="option-grid ${two?'two':''}">${values.map(([value,label])=>`<label class="option"><input type="radio" name="${name}" value="${value}" ${selected===value?'checked':''}><span>${label}</span></label>`).join('')}</div>`;}
function setupRound(ids=null,target=null){
  if(store.doc.session&&!store.doc.session.finished){showDialog('Eine Runde ist noch offen',`<p>Du kannst sie fortsetzen oder eine neue Runde beginnen. Bereits bewertete Antworten bleiben gespeichert.</p><div class="dialog-actions">${button('resume','Fortsetzen')}${button('replace-round','Neue Runde','secondary',`data-source="${h(ids?.join(',')||'')}" data-target="${h(target||'')}"`)}</div>`);return;}
  const d=data(),p=prefs(),sources=target?sorted(d.collections):[...sorted(d.collections),...sorted(d.decks)],selected=ids||sources.filter(c=>c.active!==false).map(c=>c.id);
  flow={target};showDialog(target?'Auffrisch-Test vorbereiten':'Deine nächste Runde',`<form id="round-setup"><p class="label-title">Abfragerichtung</p>${options('direction',[['de-en','Deutsch → Englisch'],['en-de','Englisch → Deutsch'],['mixed','Gemischt']],p.direction)}<p class="label-title">Wie viele Bedeutungen?</p>${options('requirement',[['any','Eine richtige reicht'],['all','Alle erforderlich']],p.requirement,true)}<p class="hint" style="margin:-8px 0 19px">Du entscheidest jedes Mal neu. Der Lernstand merkt sich die tatsächlich gewussten Bedeutungen.</p>${target?'':`<label class="field">Lernmodus<select name="mode"><option value="smart">Smart üben</option><option value="all">Alle wiederholen</option><option value="learning">Neue und unsichere Wörter</option><option value="refresh">Sichere Wörter auffrischen</option></select></label><label class="field">Wörter pro Runde<select name="limit">${[5,10,15,20,30,50].map(n=>`<option value="${n}" ${p.limit===n?'selected':''}>${n} Wörter</option>`).join('')}</select><span class="hint">Kein Tageslimit. „Alle wiederholen“ und Auffrisch-Tests fragen die gesamte Auswahl ab.</span></label>`}<p class="label-title">${target?'Welche Lektionen prüfen?':'Sammlungen auswählen'}</p><div class="pick-list">${sources.map(c=>`<label class="pick"><input type="checkbox" name="source" value="${c.id}" ${selected.includes(c.id)?'checked':''}><div><strong>${h(c.name)}</strong><div class="muted">${d.decks[c.id]?'Auffrisch-Sammlung':'Lektion'}${c.active===false?' · pausiert':''}</div></div></label>`).join('')||'<p class="empty-inline">Lege zuerst eine Sammlung an.</p>'}</div><div class="dialog-actions"><button class="btn primary" type="submit">${icon('learn')}${target?'Test starten':'Runde starten'}</button></div></form>`);
}
async function startRound(fd){
  const d=data(),direction=fd.get('direction'),requirement=fd.get('requirement'),ids=fd.getAll('source'),mode=flow?.target?'check':fd.get('mode'),limit=Number(fd.get('limit')||10);
  if(!ids.length)throw Error('Bitte mindestens eine Sammlung auswählen.');
  // Explicitly selected paused collections are usable for this round.
  const selectedData=clone(d);ids.forEach(id=>{if(selectedData.collections[id])selectedData.collections[id].active=true;if(selectedData.decks[id])selectedData.decks[id].active=true;});
  const queue=makeQueue(selectedData,ids,{direction,requirement,mode,limit});
  if(!queue.length)throw Error('Keine passenden Wörter. Wähle einen anderen Modus oder „Alle wiederholen“.');
  const session={id:uid(),queue,cursor:0,originalLength:queue.length,direction,requirement,mode,sourceIds:ids,refreshTarget:flow?.target||null,answers:[''],overrides:{},feedback:null,regions:null,regionAnswers:{},startedAt:Date.now(),finished:false};
  await store.commit([['settings','training',{id:'training',direction,requirement,limit}]],session);sync.schedule();flow=null;closeDialog();screen='round';render();
}
function renderRound(){
  const {s,item,word}=current();if(!s){screen='learn';render();return;}if(s.cursor>=s.queue.length){screen='result';renderResult();return;}
  if(!word){app.innerHTML=`<main class="round-shell"><h2>Dieses Wort wurde entfernt.</h2><p class="muted space">Dein restlicher Lernstand bleibt erhalten.</p>${button('next','Weiter','primary','style="margin-top:20px"')}</main>`;return;}
  const f=s.feedback,english=item.direction==='de-en',questions=f?regionQuestions(word,f):[],pending=f&&questions.length&&!s.regions;
  const prompt=english?wordLabel(word,'german'):groupLabel(word.english[item.promptIndex%word.english.length]);
  const context=word.context?.[english?'de':'en'];
  app.innerHTML=`<main class="round-shell"><header class="round-top"><button class="iconbtn" data-action="pause" aria-label="Runde pausieren">${icon('pause')}</button><div class="track"><i style="width:${s.cursor/s.queue.length*100}%"></i></div><small class="muted">${s.cursor+1} / ${s.queue.length}</small></header><div class="round-meta"><span class="pill">${dirLabel(item.direction)}</span><span class="pill">${s.requirement==='all'?'Alle Bedeutungen':'Eine Bedeutung reicht'}</span>${item.repeat?'<span class="pill learning">Noch einmal festigen</span>':''}</div><div class="round-prompt"><div class="eyebrow">${english?'WIE HEISST DAS AUF ENGLISCH?':'WAS BEDEUTET DAS AUF DEUTSCH?'}</div><h1 lang="${english?'de':'en'}">${h(prompt)}</h1>${context?`<p class="muted">${h(context)}</p>`:''}</div>${!f?`<form id="answer-form"><div class="answer-rows" id="answer-rows">${s.answers.map((a,i)=>answerInput(a,i,item.direction)).join('')}</div><button class="textbtn add-answer" type="button" data-action="add-answer">${icon('plus')} Weitere Bedeutung</button><p class="hint">${english?'Die englische Schreibweise zählt.':'Deutsche Tippfehler zählen nicht.'}</p><footer class="round-footer"><button type="button" class="textbtn" data-action="skip">Weiß ich noch nicht</button><button class="btn primary" type="submit">Prüfen ${icon('check')}</button></footer></form>`:`<div class="answer-rows">${f.rows.filter(r=>r.kind!=='empty').map(r=>`<div class="answer-result ${r.kind}"><span class="indicator">${['wrong','spelling'].includes(r.kind)?'×':'✓'}</span><div class="grow"><span class="answer-text">${h(r.answer)}</span>${r.kind==='spelling'?'<p class="hint">Englischer Schreibfehler</p>':r.kind==='typo'||r.kind==='manual'?'<p class="hint">Tippfehler · richtig gewertet</p>':r.kind==='duplicate'?'<p class="hint">Bereits angegeben</p>':''}</div>${!english&&['wrong','typo','manual'].includes(r.kind)?`<button class="textbtn" data-action="${r.kind==='wrong'?'accept-typo':'reject-typo'}" data-index="${r.index}">${r.kind==='wrong'?'War nur ein Tippfehler':'Doch falsch'}</button>`:''}</div>`).join('')}</div><section class="feedback ${f.grade}" aria-live="polite"><h2>${f.grade==='full'?'Richtig!':f.grade==='partial'?'Ein Teil stimmt schon.':'Noch einmal üben.'}</h2><p>${f.grade==='full'?(s.requirement==='any'?'Eine richtige Bedeutung reicht für diese Runde.':'Du hast alle geforderten Bedeutungen gewusst.'):f.grade==='partial'?'Für „alle Bedeutungen“ fehlt noch etwas.':english?'Achte auch auf die genaue englische Schreibweise.':'Schau dir die hinterlegten Buchantworten an.'}${f.grade==='full'&&f.hasWrong?' Eine zusätzliche Antwort war falsch; sie ist oben markiert.':''}</p></section>${pending?'':solution(word,f)}${questions.length?`<section class="region-box"><h2>${s.regions?'Deine Zuordnung':'Britisch oder amerikanisch?'}</h2>${!s.regions?`<p>Die Übersetzung stimmt. Ordne jetzt deine eingegebenen Varianten zu.</p><form id="region-form">${questions.map(q=>`<label class="region-line"><strong lang="en">${h(q.answer)}</strong><select name="${q.id}" required><option value="">Bitte zuordnen</option><option value="UK" ${s.regionAnswers?.[q.id]==='UK'?'selected':''}>Britisch</option><option value="US" ${s.regionAnswers?.[q.id]==='US'?'selected':''}>Amerikanisch</option></select></label>`).join('')}<button type="submit" class="btn primary wide">Zuordnung prüfen</button></form>`:s.regions.map(r=>`<p class="region-result ${r.correct?'':'wrong'}">${r.correct?'✓':'×'} ${h(questions.find(q=>q.id===r.id)?.answer)} → ${r.expected==='UK'?'Britisch':'Amerikanisch'}${r.correct?'':' · Zuordnung noch üben'}</p>`).join('')}</section>`:''}${!pending?`<footer class="round-footer"><button class="textbtn" data-action="round-add-refresh">${icon('refresh')} Auffrischen</button><button class="btn primary" data-action="next">Weiter ${icon('arrow')}</button></footer>`:''}`}</main>`;
}
function answerInput(value,index,direction){const en=direction==='de-en';return `<div class="answer-row"><span class="number">${index+1}</span><input name="answer" value="${h(value)}" aria-label="${en?'Englische':'Deutsche'} Bedeutung ${index+1}" placeholder="${en?'Englische':'Deutsche'} Bedeutung" lang="${en?'en':'de'}" inputmode="text" autocomplete="${en?'off':'on'}" autocorrect="${en?'off':'on'}" autocapitalize="${en?'none':'sentences'}" spellcheck="${en?'false':'true'}" maxlength="300">${index?`<button type="button" class="iconbtn" data-action="remove-answer" aria-label="Antwortfeld entfernen">${icon('close')}</button>`:''}</div>`;}
function solution(word,f){return `<p class="solution"><strong>Buchantworten:</strong> ${targetGroups(word,f.direction).map(g=>`<span class="${f.missing.includes(g.id)&&f.requirement==='all'?'missing':''}">${h(groupLabel(g))}${g.region?` <small>(${g.region==='UK'?'brit.':'amer.'})</small>`:''}</span>`).join(', ')}</p>`;}
function readAnswers(){return [...document.querySelectorAll('#answer-rows input')].map(el=>el.value);}
async function saveDraft(){clearTimeout(sessionTimer);if(screen!=='round')return;const {s}=current();if(!s||s.feedback)return;const answers=readAnswers();if(!answers.length)return;await store.update(doc=>{if(doc.session?.id===s.id&&doc.session.cursor===s.cursor&&!doc.session.feedback)doc.session.answers=answers;return doc;});}
async function checkAnswer(skip=false){
  clearTimeout(sessionTimer);const {s,item,word}=current();if(!word||s.feedback)return;
  s.answers=skip?['']:readAnswers();if(!skip&&!s.answers.some(a=>a.trim()))throw Error('Gib eine Antwort ein oder wähle „Weiß ich noch nicht“.');
  s.overrides={};s.feedback=evaluate(word,s.answers,item.direction,s.requirement);s.regions=null;s.regionAnswers={};
  const r={id:s.id+'_'+s.cursor,sessionId:s.id,wordId:word.id,direction:item.direction,requirement:s.requirement,result:s.feedback,at:Date.now(),repeat:item.repeat,regionPending:regionQuestions(word,s.feedback).length>0};
  await store.commit([['reviews',r.id,r]],s);sync.schedule();render();
}
async function recheck(){const {s,item,word}=current();s.feedback=evaluate(word,s.answers,item.direction,s.requirement,s.overrides);const id=s.id+'_'+s.cursor;await store.commit([['reviews',id,{...data().reviews[id],result:s.feedback}]],s);sync.schedule();render();}
async function next(){const {s,item}=current();if(!s)return;const pending=current().word&&s.feedback&&regionQuestions(current().word,s.feedback).length&&!s.regions;if(pending)return;
  if(item&&!item.repeat&&s.mode!=='check'&&s.feedback&&(s.feedback.grade!=='full'||s.regions?.some(r=>!r.correct)))s.queue.push({...item,repeat:true});
  s.cursor++;s.answers=[''];s.feedback=null;s.overrides={};s.regions=null;s.regionAnswers={};s.finished=s.cursor>=s.queue.length;
  await store.update(doc=>{doc.session=s;return doc;});screen=s.finished?'result':'round';render();window.scrollTo(0,0);}
function sessionReviews(){const s=store.doc.session;return Object.values(data().reviews).filter(r=>r.sessionId===s?.id&&!r.repeat).sort((a,b)=>a.at-b.at);}
function renderResult(){const s=store.doc.session;if(!s){screen='learn';render();return;}const reviews=sessionReviews(),wrong=reviews.filter(r=>r.result.grade!=='full'||r.regions?.some(x=>!x.correct));
  app.innerHTML=`<main class="round-shell round-result"><div data-sync>${status()}</div><header class="result-head"><img src="./icon.svg" alt=""><div class="eyebrow">RUNDE GESCHAFFT</div><h1>Ein gutes Stück<br>weiter.</h1><p>${reviews.length} Vokabeln geübt. Dein Lernstand ist gespeichert.</p></header><div class="result-stats">${[['full','Richtig'],['partial','Teilweise'],['wrong','Wiederholen']].map(([g,label])=>`<div><strong>${reviews.filter(r=>r.result.grade===g).length}</strong><small>${label}</small></div>`).join('')}</div>${reviews.some(r=>r.regions?.some(x=>!x.correct))?'<div class="notice">Einige Übersetzungen waren richtig, die britisch/amerikanische Zuordnung braucht noch Übung.</div>':''}<p class="small muted" style="margin-bottom:14px">Die erste Antwort zählt für den Lernstand. Wiederholungen festigen das Gelernte.</p>${wrong.length?`<div class="word-list">${wrong.slice(0,20).map(r=>{const w=data().words[r.wordId];return w?`<div class="word-row"><div class="grow"><strong>${h(wordLabel(w,'english'))}</strong><p>${dirLabel(r.direction)}</p></div><span class="pill learning">${r.result.grade==='full'?'Zuordnung':gradeLabel(r.result.grade)}</span></div>`:'';}).join('')}</div>`:''}<div class="stack space" style="gap:11px">${button('save-result-refresh',icon('refresh')+(s.refreshTarget?'Wörter in Auffrisch-Sammlung übernehmen':'Fürs Auffrischen auswählen'),'secondary')}${button('finish','Zur Übersicht '+icon('arrow'))}</div></main>`;
}

function collectionDialog(id=null,deck=false){const c=id?(data().decks[id]||data().collections[id]):null;showDialog(c?'Sammlung umbenennen':deck?'Neue Auffrisch-Sammlung':'Neue Sammlung',`<form id="collection-form" data-id="${h(id||'')}" data-deck="${deck||!!data().decks[id]}"><label class="field">Name<input name="name" value="${h(c?.name||'')}" maxlength="100" placeholder="${deck?'Zum Beispiel: Für den nächsten Test':'Zum Beispiel: Unit 1'}" required autofocus></label><div class="dialog-actions"><button class="btn primary" type="submit">${c?'Speichern':'Anlegen'}</button></div></form>`);}
function editorLine(g,language){return `<div class="meaning-line" data-group="${h(g?.id||'')}"><input name="${language}" aria-label="${language==='en'?'Englische':'Deutsche'} Buchbedeutung" value="${h(g?.answers.join(' / ')||'')}" placeholder="${language==='en'?'Englische Bedeutung':'Deutsche Bedeutung'}" maxlength="2000" lang="${language}" required>${language==='en'?`<select name="region" aria-label="Englische Sprachvariante"><option value="">Neutral</option><option value="UK" ${g?.region==='UK'?'selected':''}>Britisch</option><option value="US" ${g?.region==='US'?'selected':''}>Amerikanisch</option></select>`:''}<button type="button" class="iconbtn" data-action="remove-group" aria-label="Bedeutung entfernen">${icon('close')}</button></div>`;}
function wordDialog(id=null){const w=id?data().words[id]:null;showDialog(w?'Vokabel bearbeiten':'Neue Vokabel',`<form id="word-form" data-id="${h(id||'')}" data-collection="${h(w?.collectionId||(!data().decks[detail]?detail:'')||'')}"><p class="label-title">Englische Buchbedeutungen</p><div id="english-groups">${(w?.english||[null]).map(g=>editorLine(g,'en')).join('')}</div><button type="button" class="textbtn" data-action="add-group" data-language="en">${icon('plus')} Englische Bedeutung</button><div class="divider"></div><p class="label-title">Deutsche Buchbedeutungen</p><div id="german-groups">${(w?.german||[null]).map(g=>editorLine(g,'de')).join('')}</div><button type="button" class="textbtn" data-action="add-group" data-language="de">${icon('plus')} Deutsche Bedeutung</button><p class="hint space">Eine geforderte Bedeutung pro Feld. Gleichwertige Buchantworten innerhalb eines Feldes mit „ / “ trennen. Britische und amerikanische Varianten bekommen je ein eigenes Feld.</p><details><summary>Kontexthinweise aus dem Buch</summary><label class="field">Hinweis bei Deutsch → Englisch<input name="context-de" maxlength="300" value="${h(w?.context?.de||'')}" placeholder="Zum Beispiel: im Sinne von herstellen"></label><label class="field">Hinweis bei Englisch → Deutsch<input name="context-en" maxlength="300" value="${h(w?.context?.en||'')}"></label></details><div class="dialog-actions">${w?button('delete-word','Wort löschen','danger',`data-id="${id}"`):''}<button class="btn primary" type="submit">Speichern</button></div></form>`);}
function groupsFromEditor(language,w){return [...document.querySelectorAll(language==='en'?'#english-groups .meaning-line':'#german-groups .meaning-line')].map(row=>{const answers=row.querySelector('input').value.split(/\s+\/\s+/).map(x=>x.trim()).filter(Boolean),region=row.querySelector('select')?.value,old=(language==='en'?w?.english:w?.german)?.find(g=>g.id===row.dataset.group);return {id:old&&JSON.stringify(old.answers)===JSON.stringify(answers)&&old.region===(region||undefined)?old.id:uid(),answers,...(region?{region}:{})};});}
function wordStats(id){const d=data(),w=d.words[id],p=prefs();showDialog('Dein Lernstand',`<p><strong>${h(wordLabel(w,'english'))}</strong> — ${h(wordLabel(w,'german'))}</p>${['de-en','en-de'].map(dir=>{const stat=progressFor(w,d.reviews,dir,p.requirement);return `<section class="panel" style="margin-bottom:15px"><h3>${dirLabel(dir)}</h3><div class="result-stats" style="margin:16px 0"><div><strong>${stat.seen}</strong><small>Abfragen</small></div><div><strong>${stat.errors}</strong><small>Falsch</small></div><div><strong>${stat.partial}</strong><small>Teilweise</small></div></div>${dir==='de-en'?`<p class="small muted">${stat.spellingErrors} Schreibfehler · ${stat.regionErrors} falsche Zuordnungen</p>`:''}${targetGroups(w,dir).map(g=>`<div class="history-line"><span>${h(groupLabel(g))}</span><span class="muted">${stat.groupStats[g.id].correct}× gewusst</span></div>`).join('')}<p class="hint space">${stat.last?'Zuletzt: '+new Date(stat.last).toLocaleDateString('de-DE'):'Noch nicht abgefragt.'}</p></section>`;}).join('')}`);}
function openImport(kind=null){candidate=null;importKind=kind;showDialog('Sammlung importieren',`<p>Wordlo erkennt automatisch, ob die Datei eine normale Sammlung oder eine Auffrisch-Sammlung enthält.</p><label class="file-drop">${icon('upload')}<strong>JSON-Datei auswählen</strong><span class="hint">Sammlung, Auffrischen oder Lernstandsicherung</span><input id="import-file" type="file" accept=".json,application/json" aria-label="JSON-Datei auswählen"></label><details><summary>JSON-Text einfügen</summary><textarea id="import-text" aria-label="JSON-Text" spellcheck="false" placeholder="JSON hier einfügen …"></textarea><button class="btn secondary space" data-action="parse-json">Vorschau anzeigen</button></details><div id="import-preview"></div>`);}
function validateBackup(input){
  if(input.schema!==1||!input.data||entities.some(e=>!input.data[e]||typeof input.data[e]!=='object'||Array.isArray(input.data[e])))throw Error('Die Sicherungsdatei ist unvollständig.');
  for(const entity of entities)for(const [id,value] of Object.entries(input.data[entity])){if(!safeId(id)||!value||typeof value!=='object'||Array.isArray(value))throw Error('Ungültige Sicherungsdatei.');}
  for(const w of Object.values(input.data.words)){cleanWord(w,w.collectionId);if(w.collectionId&&!input.data.collections[w.collectionId])throw Error('Eine Vokabel verweist auf eine fehlende Sammlung.');}
  for(const c of [...Object.values(input.data.collections),...Object.values(input.data.decks)]){if(typeof c.name!=='string'||!c.name.trim())throw Error('Ein Sammlungsname fehlt.');}
  for(const deck of Object.values(input.data.decks))if(!Array.isArray(deck.members)||deck.members.some(m=>!input.data.words[m.wordId]||!Number.isFinite(m.addedAt)))throw Error('Ungültige Auffrisch-Sammlung.');
  for(const r of Object.values(input.data.reviews))if(!['de-en','en-de'].includes(r.direction)||!['any','all'].includes(r.requirement)||!Number.isFinite(r.at)||!r.result||!Array.isArray(r.result.matched)||!Array.isArray(r.result.rows)||!['full','partial','wrong'].includes(r.result.grade))throw Error('Ungültiger Lernstand in der Sicherung.');
  return {type:'backup',data:input.data};
}
function previewImport(text){
  if(text.length>15000000)throw Error('Die Datei ist zu groß (maximal 15 MB).');
  let parsed;try{parsed=JSON.parse(text);}catch{throw Error('Die Datei enthält keinen gültigen JSON-Text.');}
  candidate=parsed.format==='wordlo-backup'?validateBackup(parsed):parseImport(parsed,data());
  if(candidate.type==='backup'){$('#import-preview').innerHTML=`<div class="divider"></div><h3>Lernstand wiederherstellen</h3><p class="small muted space">${Object.keys(candidate.data.words).length} Vokabeln, ${Object.keys(candidate.data.reviews).length} Bewertungen. Vorhandene Einträge mit gleicher Kennung werden durch die Sicherung ersetzt. Andere Einträge bleiben erhalten. Die Google-Verbindung bleibt unverändert.</p>${button('confirm-import','Sicherung übernehmen','primary','style="margin-top:18px"')}`;return;}
  const c=candidate;$('#import-preview').innerHTML=`<div class="divider"></div><span class="pill">${c.type==='refresh'?'Auffrisch-Sammlung':'Normale Sammlung'}</span><h3 style="margin-top:13px">${h((c.deck||c.collection).name)}</h3><div class="import-counts"><span>${c.count} Wörter</span><span>${c.linked} verknüpft</span><span>${c.words.length} neu</span>${c.skipped?`<span>${c.skipped} doppelte übersprungen</span>`:''}</div><ul class="preview-list">${c.words.slice(0,6).map(w=>`<li><strong>${h(wordLabel(w,'english'))}</strong><br>${h(wordLabel(w,'german'))}</li>`).join('')}</ul>${c.type==='refresh'?'<p class="hint">Bereits vorhandene Wörter behalten ihren Lernstand. Neue Wörter liegen direkt in der Auffrisch-Sammlung.</p>':''}${button('confirm-import','Jetzt importieren','primary','style="margin-top:18px"')}`;
}
function download(name,value){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function deckPicker(id,{wordIds=null,result=false,single=false}={}){
  const d=data(),deck=d.decks[id],words=wordIds?wordIds.map(id=>d.words[id]).filter(Boolean):Object.values(d.words).filter(w=>w.collectionId),selected=new Set(result?wordIds:deck?.members.map(m=>m.wordId)||[]);
  flow={deckId:id,words:words.map(w=>w.id),result,single};
  const allResult=result?[...new Set(sessionReviews().map(r=>r.wordId))].map(id=>d.words[id]).filter(Boolean):words;
  flow.words=allResult.map(w=>w.id);
  showDialog(result?'Wörter fürs Auffrischen':single?'Zur Auffrisch-Sammlung':'Wörter auswählen',`<form id="deck-members"><label class="field">Auffrisch-Sammlung<select name="deck">${sorted(d.decks).map(c=>`<option value="${c.id}" ${id===c.id?'selected':''}>${h(c.name)}</option>`).join('')}<option value="new" ${!id?'selected':''}>Neue Auffrisch-Sammlung …</option></select></label><label class="field">Name für eine neue Sammlung<input name="new-name" maxlength="100" placeholder="Zum Beispiel: Wiederholung September"></label>${!single?`<input type="search" id="pick-search" placeholder="Wörter oder Lektion suchen …" aria-label="Wörter auswählen und suchen"><div class="row wrap space"><button type="button" class="textbtn" data-action="pick-all">Sichtbare auswählen</button><button type="button" class="textbtn" data-action="pick-none">Auswahl leeren</button></div>`:''}<div class="pick-list" id="word-picks">${allResult.map(w=>`<label class="pick" data-search-text="${h(normalize(wordLabel(w,'english')+' '+wordLabel(w,'german')+' '+(d.collections[w.collectionId]?.name||'')))}"><input name="word" type="checkbox" value="${w.id}" ${selected.has(w.id)||single?'checked':''}><div class="grow"><strong>${h(wordLabel(w,'english'))}</strong><div class="muted">${h(wordLabel(w,'german'))}${w.collectionId?' · '+h(d.collections[w.collectionId]?.name):''}</div></div></label>`).join('')||'<p class="empty-inline">Noch keine Wörter vorhanden. Du kannst auch eine Auffrisch-Datei importieren.</p>'}</div><div class="dialog-actions"><button class="btn primary" type="submit">${result?'Auswahl übernehmen':'Hinzufügen'}</button></div></form>`);
}
function confirmDelete(entity,id){const d=data(),word=entity==='words',deck=entity==='decks',name=word?wordLabel(d.words[id],'english'):d[entity][id].name;showDialog('Wirklich löschen?',`<p><strong>${h(name)}</strong></p><p>${word?'Das Wort wird aus deinen Sammlungen und Auffrisch-Listen entfernt.':deck?'Die Auffrisch-Liste wird gelöscht. Wörter aus normalen Sammlungen und ihre Lernstände bleiben erhalten.':'Die Sammlung wird gelöscht. Wörter, die in Auffrisch-Listen verwendet werden, bleiben dort erhalten.'}</p><div class="dialog-actions">${button('close','Abbrechen','secondary')}${button('confirm-delete','Löschen','danger',`data-entity="${entity}" data-id="${id}"`)}</div>`);}
function conflictsDialog(){showDialog('Änderungen vergleichen',`<p>Diese Einträge wurden auf mehreren Geräten geändert. Wähle, welche Version gelten soll.</p><form id="conflict-form">${sync.conflicts.map((c,i)=>`<section class="panel" style="margin-bottom:12px"><strong>${h(c.local.value?.name||c.local.value?.english?.[0]?.answers?.[0]||c.key.split(':')[0])}</strong><p class="small space">Gerät: ${h(describeValue(c.local.value))}</p><p class="small space">Google: ${h(describeValue(c.remote.value))}</p><label class="field space">Behalten<select name="choice-${i}" required><option value="">Bitte wählen</option><option value="local">Dieses Gerät</option><option value="cloud">Google</option></select></label></section>`).join('')}<button type="submit" class="btn primary wide">Auswahl übernehmen</button></form>`);}
function describeValue(v){if(v===null)return 'Gelöscht';if(v.english)return wordLabel(v,'english')+' — '+wordLabel(v,'german');if(v.name)return v.name+(v.members?` · ${v.members.length} Wörter`:'');if(v.result)return gradeLabel(v.result.grade)+' · '+(v.result.rows||[]).map(r=>r.answer).join(', ');return JSON.stringify(v).slice(0,250);}

document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-action]');if(!b||b.disabled||busy)return;const action=b.dataset.action,id=b.dataset.id;
  try{busy=true;
    switch(action){
      case 'close':closeDialog();break;
      case 'nav':case 'cloud-settings':screen=action==='cloud-settings'?'settings':b.dataset.screen;detail=null;search='';render();window.scrollTo(0,0);break;
      case 'open':detail=id;screen=data().decks[id]?'refresh':'collections';search='';render();break;
      case 'back':detail=null;search='';render();break;
      case 'setup':setupRound(id?[id]:null);break;
      case 'replace-round':await store.update(doc=>{doc.session=null;return doc;});setupRound(b.dataset.source?b.dataset.source.split(','):null,b.dataset.target||null);break;
      case 'resume':closeDialog();screen=store.doc.session?.finished?'result':'round';render();break;
      case 'pause':await saveDraft();screen='learn';render();break;
      case 'add-answer':{const {item}=current();const container=$('#answer-rows');if(container.children.length>=30)throw Error('Höchstens 30 Antwortfelder.');container.insertAdjacentHTML('beforeend',answerInput('',container.children.length,item.direction));container.lastElementChild.querySelector('input').focus();await saveDraft();break;}
      case 'remove-answer':b.closest('.answer-row').remove();document.querySelectorAll('.answer-row .number').forEach((el,i)=>el.textContent=i+1);await saveDraft();break;
      case 'skip':await checkAnswer(true);break;
      case 'next':await next();break;
      case 'finish':await store.update(doc=>{doc.session=null;return doc;});screen='learn';render();break;
      case 'accept-typo':{const {word,item}=current();if(item.direction!=='en-de')break;showDialog('Welche Bedeutung meintest du?',`<p>Wähle die Buchbedeutung, die du trotz Tippfehler gemeint hast.</p><div class="stack" style="gap:10px">${word.german.map(g=>button('confirm-typo',h(groupLabel(g)),'secondary',`data-group="${g.id}" data-index="${b.dataset.index}"`)).join('')}</div>`);break;}
      case 'confirm-typo':{const {s,item}=current();if(item.direction!=='en-de')break;s.overrides[b.dataset.index]=b.dataset.group;closeDialog();await recheck();break;}
      case 'reject-typo':{const {s,item}=current();if(item.direction!=='en-de')break;s.overrides[b.dataset.index]='wrong';await recheck();break;}
      case 'new-collection':collectionDialog();break;
      case 'new-deck':collectionDialog(null,true);break;
      case 'rename':collectionDialog(id);break;
      case 'new-word':wordDialog();break;
      case 'edit-word':wordDialog(id);break;
      case 'word-stats':wordStats(id);break;
      case 'add-group':{const lang=b.dataset.language;const container=$(lang==='en'?'#english-groups':'#german-groups');if(container.children.length>=30)throw Error('Höchstens 30 Bedeutungen pro Sprache.');container.insertAdjacentHTML('beforeend',editorLine(null,lang));container.lastElementChild.querySelector('input').focus();break;}
      case 'remove-group':if(b.parentElement.parentElement.children.length>1)b.parentElement.remove();break;
      case 'delete-word':confirmDelete('words',id);break;
      case 'delete-collection':confirmDelete(data().decks[id]?'decks':'collections',id);break;
      case 'confirm-delete':{const entity=b.dataset.entity,d=data(),changes=[[entity,id,null]];
        if(entity==='collections')for(const w of Object.values(d.words).filter(w=>w.collectionId===id)){if(Object.values(d.decks).some(deck=>deck.members.some(m=>m.wordId===w.id)))changes.push(['words',w.id,{...w,collectionId:null}]);else changes.push(['words',w.id,null]);}
        if(entity==='words')for(const deck of Object.values(d.decks))if(deck.members.some(m=>m.wordId===id))changes.push(['decks',deck.id,{...deck,members:deck.members.filter(m=>m.wordId!==id)}]);
        if(entity==='decks')for(const m of d.decks[id].members){const w=d.words[m.wordId];if(w&&!w.collectionId&&!Object.values(d.decks).some(deck=>deck.id!==id&&deck.members.some(x=>x.wordId===w.id)))changes.push(['words',w.id,null]);}
        await store.commit(changes);sync.schedule();closeDialog();render();notify('Gelöscht.');break;}
      case 'toggle-all':{const entity=screen==='refresh'?'decks':'collections';await store.commit(Object.values(data()[entity]).map(c=>[entity,c.id,{...c,active:b.dataset.value==='true'}]));sync.schedule();render();break;}
      case 'import':openImport(b.dataset.kind||null);break;
      case 'parse-json':previewImport($('#import-text').value);break;
      case 'confirm-import':{if(!candidate)break;const c=candidate;let changes=c.type==='backup'?entities.flatMap(entity=>Object.entries(c.data[entity]).map(([id,v])=>[entity,id,v])):importChanges(c);
        // Revalidate against changes that may have arrived while the preview was open.
        if(c.type!=='backup'&&(data().collections[(c.collection||c.deck).id]||data().decks[(c.collection||c.deck).id]))throw Error('Diese Sammlung ist inzwischen bereits vorhanden.');
        await store.commit(changes);sync.schedule();candidate=null;closeDialog();detail=c.type==='backup'?null:(c.collection||c.deck).id;screen=c.type==='refresh'?'refresh':'collections';search='';render();notify(c.type==='backup'?'Lernstand übernommen.':'Sammlung importiert.');break;}
      case 'export':download('wordlo-'+id+'.json',exportCollection(data(),id));break;
      case 'backup':download('wordlo-sicherung-'+new Date().toISOString().slice(0,10)+'.json',{format:'wordlo-backup',schema:1,createdAt:new Date().toISOString(),data:data()});notify('Sicherungsdatei erstellt.');break;
      case 'deck-pick':deckPicker(id);break;
      case 'deck-test':setupRound(null,id);break;
      case 'remove-member':{const deck=data().decks[detail];await store.commit([['decks',deck.id,{...deck,members:deck.members.filter(m=>m.wordId!==id)}]]);sync.schedule();render();break;}
      case 'round-add-refresh':{const {word}=current();deckPicker(null,{wordIds:[word.id],single:true});break;}
      case 'save-result-refresh':{const s=store.doc.session,wordIds=[...new Set(sessionReviews().filter(r=>r.result.grade!=='full'||r.regions?.some(x=>!x.correct)).map(r=>r.wordId))];deckPicker(s.refreshTarget,{wordIds,result:true});break;}
      case 'pick-all':document.querySelectorAll('#word-picks .pick:not(.hidden) input').forEach(el=>el.checked=true);break;
      case 'pick-none':document.querySelectorAll('#word-picks input').forEach(el=>el.checked=false);break;
      case 'sync':await sync.run();if(screen==='settings')render();break;
      case 'conflicts':conflictsDialog();break;
      case 'check-update':await checkUpdate(true);break;
      case 'update':if(screen==='round')throw Error('Bitte beende oder pausiere deine Runde vor dem Update.');updateReady?.postMessage({type:'ACTIVATE'});if(!updateReady)location.reload();break;
    }
  }catch(e){error(e.message);}finally{busy=false;}
});
document.addEventListener('submit',async e=>{
  e.preventDefault();if(busy)return;const form=e.target,fd=new FormData(form);try{busy=true;
    if(form.id==='round-setup')await startRound(fd);
    if(form.id==='answer-form')await checkAnswer();
    if(form.id==='region-form'){const {s,word}=current(),questions=regionQuestions(word,s.feedback),answers=Object.fromEntries(fd);s.regions=checkRegions(questions,answers);s.regionAnswers=answers;const id=s.id+'_'+s.cursor;await store.commit([['reviews',id,{...data().reviews[id],regions:s.regions,regionPending:false}]],s);sync.schedule();render();}
    if(form.id==='collection-form'){const id=form.dataset.id||uid(),entity=form.dataset.deck==='true'?'decks':'collections',name=String(fd.get('name')).trim();if(!name)throw Error('Bitte einen Namen eingeben.');const old=data()[entity][id],value=old?{...old,name}:{id,name,active:true,...(entity==='decks'?{members:[]}:{})};await store.commit([[entity,id,value]]);sync.schedule();closeDialog();screen=entity==='decks'?'refresh':'collections';detail=id;search='';render();}
    if(form.id==='word-form'){const old=data().words[form.dataset.id],id=old?.id||uid(),collectionId=form.dataset.collection||null;const word=cleanWord({id,english:groupsFromEditor('en',old),german:groupsFromEditor('de',old),context:{de:String(fd.get('context-de')||''),en:String(fd.get('context-en')||'')}},collectionId);await store.commit([['words',id,word]]);sync.schedule();closeDialog();render();notify('Vokabel gespeichert.');}
    if(form.id==='deck-members'){const wordIds=fd.getAll('word').filter(id=>data().words[id]);if(!wordIds.length)throw Error('Bitte mindestens ein Wort auswählen.');const isNew=fd.get('deck')==='new',id=isNew?uid():fd.get('deck'),old=data().decks[id],name=isNew?String(fd.get('new-name')||'').trim():old?.name;if(!name)throw Error('Bitte einen Namen für die neue Auffrisch-Sammlung eingeben.');const before=new Map((old?.members||[]).map(m=>[m.wordId,m]));for(const wordId of wordIds)before.set(wordId,{wordId,addedAt:Date.now()});const deck={id,name,active:old?.active!==false,members:[...before.values()]};await store.commit([['decks',id,deck]]);sync.schedule();closeDialog();flow=null;if(screen!=='round'&&screen!=='result'){screen='refresh';detail=id;render();}notify(`${wordIds.length} Wörter fürs Auffrischen übernommen.`);}
    if(form.id==='cloud-form'){const submit=form.querySelector('[type=submit]');submit.disabled=true;const text=submit.textContent;submit.textContent='Verbindung wird geprüft …';try{await sync.configure(String(fd.get('url')||'').trim(),String(fd.get('token')||'').trim()||store.doc.config.token);render();notify(sync.conflicts.length?'Bitte Änderungen vergleichen.':sync.status==='synced'?'Google verbunden.':sync.message);}finally{if(submit.isConnected){submit.disabled=false;submit.textContent=text;}}}
    if(form.id==='conflict-form'){const choices=Object.fromEntries(sync.conflicts.map((c,i)=>[c.key,fd.get('choice-'+i)]));await sync.resolve(choices);closeDialog();render();}
  }catch(e){error(e.message);}finally{busy=false;}
});
document.addEventListener('input',e=>{
  const el=e.target;
  if(el.matches('#answer-rows input')){clearTimeout(sessionTimer);sessionTimer=setTimeout(()=>saveDraft().catch(e=>notify(e.message)),200);}
  if(el.dataset.search){search=el.value;if(el.dataset.search==='collections')$('#collection-results').innerHTML=collectionCards(sorted(screen==='refresh'?data().decks:data().collections),screen==='refresh');else $('#word-results').innerHTML=wordRows();}
  if(el.id==='pick-search')document.querySelectorAll('#word-picks .pick').forEach(row=>row.classList.toggle('hidden',!row.dataset.searchText.includes(normalize(el.value))));
});
document.addEventListener('change',async e=>{const el=e.target;try{
  if(el.dataset.toggle){const entity=el.dataset.toggle,c=data()[entity][el.dataset.id];await store.commit([[entity,c.id,{...c,active:el.checked}]]);sync.schedule();}
  if(el.id==='import-file'&&el.files[0]){if(el.files[0].size>15000000)throw Error('Die Datei ist zu groß (maximal 15 MB).');previewImport(await el.files[0].text());}
  if(el.closest('#region-form')){const {s}=current();s.regionAnswers=Object.fromEntries(new FormData($('#region-form')));await store.update(doc=>{doc.session=s;return doc;});}
}catch(e){candidate=null;error(e.message);}});
sync.addEventListener('change',()=>{renderStatus();if(sync.status==='synced'&&!modal.open&&!['round','result'].includes(screen)&&document.activeElement?.tagName!=='INPUT'){clearTimeout(renderTimer);renderTimer=setTimeout(render,80);}});
store.addEventListener('external',()=>{if(!modal.open&&!['round','result','settings'].includes(screen))render();else renderStatus();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveDraft().catch(()=>{});else {sync.schedule(0);checkUpdate().catch(()=>{});}});
window.addEventListener('pagehide',()=>saveDraft().catch(()=>{}));
let registration=null;
async function checkUpdate(manual=false){if(!registration){if(manual)notify('Offline-Updates sind in diesem Browser noch nicht bereit.');return;}try{await registration.update();if(registration.waiting){updateReady=registration.waiting;if(!['round','result'].includes(screen)&&!modal.open)render();if(manual)notify('Neue Version bereit.');}else if(manual)notify('Wordlo ist aktuell.');}catch{if(manual)notify('Update-Prüfung gerade nicht möglich. Du kannst weiterlernen.');}}
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(r=>{registration=r;updateReady=r.waiting;r.addEventListener('updatefound',()=>{const worker=r.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){updateReady=r.waiting;if(!['round','result'].includes(screen)&&!modal.open)render();}});});}).catch(()=>{});let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;location.reload();});}
render();sync.schedule(0);setInterval(()=>{if(document.visibilityState==='visible')sync.schedule(0);},60000);
